     font-size: 1.5rem;
     color: var(--accent-color);
 }

 p {
     font-size: 0.9rem;
     color: #a0a0a0;
     margin-bottom: 1.5rem;
 }

 .form-field {
     margin-bottom: 1.5rem;
 }

 .checkbox-wrapper {
     display: flex;
     align-items: flex-start;
     gap: 0.75rem;
     cursor: pointer;
 }

 input[type="checkbox"] {
     appearance: none;
     -webkit-appearance: none;
     width: 20px;
     height: 20px;
     border: 2px solid var(--accent-color);
     border-radius: 4px;
     background-color: var(--input-bg);
     cursor: pointer;
     position: relative;
     flex-shrink: 0;
     margin-top: 2px;
 }

 input[type="checkbox"]:checked {
     background-color: var(--accent-color);
 }

 input[type="checkbox"]:checked::after {
     content: '✓';
     position: absolute;
     top: 50%;
     left: 50%;
     transform: translate(-50%, -50%);
     color: var(--bg-color);
     font-weight: bold;
     font-size: 14px;
 }

 input[type="checkbox"]:focus {
     outline: 2px solid var(--accent-color);
     outline-offset: 2px;
 }

 label {
     font-size: 1rem;
     cursor: pointer;
     user-select: none;
 }

 .helper-text {
     display: block;
     margin-top: 0.5rem;
     font-size: 0.8rem;
     color: #888;
 }

 .error .helper-text {
     color: var(--error-color);
 }

 .error input[type="checkbox"] {
     border-color: var(--error-color);
 }

 button {
     width: 100%;
     padding: 0.75rem;
     border: none;
     border-radius: var(--border-radius);
     background-color: var(--accent-color);
     color: var(--bg-color);
     font-weight: 600;
     font-size: 1rem;
     cursor: pointer;
     transition: var(--transition);
 }

 button:hover {
     filter: brightness(1.1);
     transform: translateY(-1px);
 }

 button:active {
     transform: translateY(0);
 }

 #message {
     margin-top: 1rem;
     text-align: center;
     font-size: 0.9rem;
 }

 #message.success {
     color: #81c784;
 }

 .hidden {
     display: none;
 }

